const fs=require('node:fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
const prefix='school/family-android/app/src/main/assets/';
function fixture(role='parent'){
 const dom=new JSDOM('<!doctype html><html><head></head><body><div id="toasts"></div><div id="root"></div></body></html>',{url:'https://maakit.in/school/',runScripts:'dangerously',pretendToBeVisual:true});
 const w=dom.window;w.fetch=()=>new Promise(()=>{});w.scrollTo=()=>{};w.matchMedia=()=>({matches:false});
 w.HTMLDialogElement.prototype.showModal=function(){this.setAttribute('open','')};w.HTMLDialogElement.prototype.close=function(){this.removeAttribute('open')};
 const app=w.document.createElement('script');app.textContent=fs.readFileSync('school/app.js','utf8');w.document.head.appendChild(app);
 const fz=w.document.createElement('script');fz.textContent=fs.readFileSync('school/family-zone.js','utf8');w.document.head.appendChild(fz);
 w.eval("STATUS={school:'QA School',teachers:[]};U={role:"+JSON.stringify(role)+"};S=emptyState();S.settings={school:'QA School',session:'2026-27'};PD={kids:[{id:'qa1',name:'QA Child One',cls:'5th'},{id:'qa2',name:'QA Child Two',cls:'3rd'}],att:[{sid:'qa1',date:todayISO(),present:true},{sid:'qa2',date:todayISO(),present:false}],hw:[{cls:'5th',date:todayISO(),subj:'Maths',hw:'QA homework ONE',topic:'Fractions'},{cls:'3rd',date:todayISO(),subj:'English',hw:'QA homework TWO',topic:'Nouns'}],marks:[{sid:'qa1',exam:'e1',subj:'Maths',mark:42,max:50}],behav:[],speak:[],remarks:[],notices:[],fees:null};S.exams=[{id:'e1',name:'QA Exam',date:todayISO()}];PKID='qa1';view='phome';");
 w.eval(fs.readFileSync(prefix+'language.js','utf8'));w.eval(fs.readFileSync(prefix+'family-style.js','utf8'));w.eval(fs.readFileSync(prefix+'family-ui.js','utf8'));w.SNFamily.closeIntro();
 return {dom,w};
}
let {dom,w}=fixture();
// WhatsApp look (27 Nov 2026): Home = chat list, children = Status circles, Homework / Notices = chat bubbles, 5 bottom tabs
assert.equal(w.document.querySelectorAll('.fam-tab').length,5);
assert(w.document.querySelector('.fam-child').textContent.includes('QA') && w.document.querySelector('.fam-child').textContent.includes('5th'),'children as Status circles (first name + class)');
assert(w.document.querySelectorAll('.wa-row').length>=4,'chat list rows');
assert(w.document.querySelector('.fam-stats').textContent.includes('100%'),'attendance row shows the attendance %');
assert(w.document.querySelector('.fam-real-screen').textContent.includes('QA homework ONE'),'homework row shows the latest homework of the chosen child');
assert(!w.document.querySelector('.fam-real-screen').textContent.includes('QA homework TWO'),'never the sibling\'s homework on the first child');
w.eval("view='phw';render()");
assert(w.document.querySelector('.fam-phone').classList.contains('wa-wall'),'homework opens as a chat');
assert(w.document.querySelector('.wa-chat').textContent.includes('QA homework ONE'));
assert(!w.document.querySelector('.wa-chat').textContent.includes('QA homework TWO'));
w.eval("PKID='qa2';render()");
assert(w.document.querySelector('.wa-chat').textContent.includes('QA homework TWO'));
assert(!w.document.querySelector('.wa-chat').textContent.includes('QA homework ONE'));
w.eval("PKID='qa1';view='presults';render()");
assert(w.document.querySelector('.fam-real-screen').textContent.includes('42 / 50'));
assert(w.document.querySelector('.wa-chathead'),'inner screens have the chat header with a back arrow');
w.eval("view='pfees';render()");
assert(!w.document.querySelector('.fam-real-screen').textContent.includes('could not open'));
w.eval("view='pnotices';render()");
assert(w.document.querySelector('.fam-real-screen').textContent.includes('Change PIN'));
// Family Zone (27 Nov 2026): tomorrow, calendar, record, Gyaan Zone, status stories, settings
w.eval("PD.tt={'5th':[0,1,2,3,4,5].map(()=>[{s:'Maths',t:'QA Teacher'},{s:'Hindi',t:'QA Two'},null,{s:'EVS',t:'QA Three'},null,null,null])};PD.attSum={qa1:{present:18,total:20},qa2:{present:10,total:20}};view='phome';render()");
assert(w.document.querySelector('.fz-status')&&w.document.querySelectorAll('.fz-status button').length>=6,'status stories on home');
assert(w.document.querySelector('.fam-stats').textContent.includes('Next school day')&&w.document.querySelector('.fam-stats').textContent.includes('Maths, Hindi, EVS'),'tomorrow row lists the subjects');
assert(w.document.querySelector('.fam-stats').textContent.includes('Attendance 90% this session'),'record row shows the session attendance');
w.eval("gyOpen(0)");assert(w.document.querySelector('#gy-story .gy-body'),'status story opens full screen');w.eval("gyClose()");assert(!w.document.querySelector('#gy-story'));
w.eval("view='ptmr';render()");
assert(w.document.querySelector('.fam-real-screen').textContent.includes('QA Teacher')&&w.document.querySelectorAll('.fz-bag label').length===4,'tomorrow: bells with teacher + bag list (3 subjects + diary)');
w.eval("view='pcal';render()");assert(w.document.querySelectorAll('.fz-day').length>=28,'month calendar');
w.eval("view='prec';render()");assert(w.document.querySelectorAll('.fz-badges > div').length===14&&w.document.querySelector('.fam-real-screen').textContent.includes('18 of 20 days'),'record: badges + session attendance');
w.eval("view='pzone';FZTAB='stories';render()");assert(w.document.querySelectorAll('.fz-card').length===8,'Gyaan Zone stories');
w.eval("view='pset';render()");assert(w.document.querySelector('.fz-week')&&w.document.querySelector('.fam-real-screen').textContent.includes('Larger text'),'settings: screen time + bigger text');
w.eval("PKID='qa2';view='ptmr';render()");assert(w.document.querySelector('.fam-real-screen').textContent.includes('not shared'),'no timetable of another class leaks into the sibling');
// Results + rankers + homework/copy checks (27 Nov 2026): home shows the class rank, never the game level
w.eval("PD.term=[{sid:'qa1',exam:'Half-Yearly',cls:'5th',rows:[{s:'Maths',pt:9,nb:5,sea:5,te:72,t:91,ab:false}],tot:91,max:100,pct:91,rank:1,of:30,complete:true,toppers:[{rank:1,name:'QA Child One',pct:91},{rank:2,name:'QA Rival',pct:88}]}];PD.checks={hw:[{sid:'qa1',date:todayISO(),subj:'Maths',task:'Ex 4.2',hw:'not',cp:'',by:'QA Teacher'},{sid:'qa1',date:todayISO(),subj:'Hindi',task:'Path 3',hw:'done',cp:'',by:'QA Two'},{sid:'qa2',date:todayISO(),subj:'EVS',task:'QA SIBLING TASK',hw:'done',cp:'',by:'x'}],copy:[{sid:'qa1',subj:'Maths',ch:'Fractions',st:'inc',by:'QA Teacher',at:1}]};PKID='qa1';view='phome';render()");
assert(w.document.querySelector('.fh-glance').textContent.includes('1st in class')&&!w.document.querySelector('.fh-glance').textContent.includes('Bronze'),'home glance shows the class rank, not the game level');
w.eval("view='presults';render()");assert(w.document.querySelector('.fr-rankers').textContent.includes('QA Rival')&&w.document.querySelector('.fr-card').textContent.includes('91%'),'results: half-yearly card + rankers');
w.eval("view='pchk';render()");const ck=w.document.querySelector('.fam-real-screen').textContent;assert(ck.includes('50%')&&ck.includes('Incomplete')&&!ck.includes('QA SIBLING TASK'),'checks: own child only, completion and copy status');
w.eval("PD.kids[0].info={adm:'A-101',father:'QA Father',dob:'2015-04-02'};view='pinfo';render()");assert(w.document.querySelector('.fam-real-screen').textContent.includes('QA Father')&&w.document.querySelector('.fp-hero'),'student profile');
w.eval("view='pleave';render()");assert(w.document.querySelector('#lv-from')&&w.document.querySelector('.fam-real-screen').textContent.includes('Send to class teacher'),'leave form');
w.eval("PKID='qa1';view='phome';render()");
w.SNFamily.menu();assert(w.document.querySelector('#fam-menu').open);
assert(w.document.querySelector('#fam-menu').textContent.includes('Game Zone'));
w.SNFamily.intro();assert.equal(w.document.querySelectorAll('#fam-intro').length,1);w.SNFamily.closeIntro();
w.eval("U=null;S=null;MUST={role:'parent',old:'1234'};render()");
assert(w.document.querySelector('#mc-pin'),'mandatory PIN change preserved');
assert(!w.document.querySelector('#lg-ph'),'does not bypass mandatory PIN screen');
assert.equal(w.document.querySelectorAll('#fam-intro').length,0);
dom.window.close();
({dom,w}=fixture('student'));
assert(!w.document.querySelector('.fam-tabs').textContent.includes('Fees'));
assert(w.document.querySelector('.fam-tabs').textContent.includes('Practice'));
assert(!w.document.querySelector('#fam-menu').textContent.includes('Staff'));
dom.window.close();
console.log('Family design: real ERP render, child switch/scoped homework, attendance, results, fees, student restrictions, intro, account sheet and mandatory PIN passed');
